import yaml
cfg=yaml.safe_load(open('/workspace/runs/config.yaml'))
def pc(text,markup=True):
    text=(text or '').strip()
    if markup:
        m=re.search(r"\[罪名\](.*?)(?:<eoa>|$)",text)
        if m: text=m.group(1).strip()
        elif "罪名:" in text: text=text.split("罪名:")[-1]
        text=re.sub(r"<eoa>.*","",text).strip()
    for sep in [";","；",",","，","、"]:
        if sep in text: return frozenset(p.strip() for p in text.split(sep) if p.strip())
    return frozenset([text]) if text else frozenset()
def grams(t,n):
    t="".join(t.split())
    if len(t)<n: return Counter([t]) if t else Counter()
    return Counter(t[i:i+n] for i in range(len(t)-n+1))
def build_idf(docs,n):
    df=Counter()
    for d in docs: df.update(set(grams(d,n)))
    N=len(docs)
    return {g: math.log((N+1)/(c+0.5)) for g,c in df.items()}
def sim(a,b,idf=None):
    if not a or not b: return 0.0
    if idf is None:
        return sum((a&b).values())/(sum(a.values())*sum(b.values()))**0.5
    num=sum(a[g]*b[g]*idf.get(g,0.0)**2 for g in (a.keys()&b.keys()))
    da=math.sqrt(sum(v*idf.get(g,0.0)**2 for g,v in a.items())); db=math.sqrt(sum(v*idf.get(g,0.0)**2 for g,v in b.items()))
    return num/(da*db) if da and db else 0.0
def ranker(name, mem):
    docs=[e.get('raw_question',e['input']) for e in mem]
    if name.startswith('plain'): n=int(name[-1]); idf=None
    elif name.startswith('idf'): n=int(name[-1]); idf=build_idf(docs,n)
    elif name.startswith('hybrid'):
        idf2=build_idf(docs,2); idf3=build_idf(docs,3); n=0; idf=(idf2,idf3)
    def score(q,e):
        d=e.get('raw_question',e['input'])
        if name.startswith('hybrid'):
            return sim(grams(q,2),grams(d,2),idf[0])+sim(grams(q,3),grams(d,3),idf[1])
        return sim(grams(q,n),grams(d,n),idf)
    return score
def keyfun(task):
    if task=='LawBench': return lambda e: pc(e['target'],markup=False)
    if task=='Symptom2Disease': return lambda e: e['target'].lower().strip()
    return lambda e: e['target'].lower().strip()
def rt(t):
    m=re.search(r"The reaction type is ([^.]+)\.",t); return m.group(1) if m else None
