                    if best is None or v>best[0]: best=(v,j)
                sel.append(best[1]); pool.remove(best[1])
            order=sel+[j for _,j in base if j not in sel]
        else:
            order=[j for _,j in base]
        hit=None
        for r,j in enumerate(order[:20],1):
