        if hit is not None:
            res['mrr']+=1.0/hit
            for k in ('1','3','5','8'):
                if hit<=int(k): res[k]+=1
    for k in ('1','3','5','8'): res[k]=res[k]/res['n']
    res['mrr']=res['mrr']/res['n']
    return res
